import sys; sys.path.insert(0, str(WORK))
from cvlib import *
R = np.load(WORK/'base_reads.npz'); res=np.load(WORK/'reserved.npy')
keep = np.setdiff1d(np.arange(768), res)
y=R['y'][:1024]
Mb = lambda L: R[f'mean_hidden_L{L}'][:1024][:,keep]
Ma = lambda L: np.load(f'pass_3/mean_hidden_L{L}.npy')[:,keep]
def zs(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def krr_cv(Z, y, gammas=(0.2,0.4), lams=(0.003,), k=5, seeds=(0,1)):
    out={}
    sq=(Z**2).sum(1); D2 = (sq[:,None]+sq[None,:]-2*Z@Z.T)/Z.shape[1]
    Y=np.eye(8)[y]
    for g in gammas:
        K=np.exp(-g*D2)
        for lam in lams:
            accs=[]
            for s in seeds:
                f=folds(y,k,s); S=np.zeros((len(y),8))
                for i in range(k):
                    tr=f!=i; te=f==i
                    A=np.linalg.solve(K[np.ix_(tr,tr)]+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0)); S[te]=K[np.ix_(te,tr)]@A
                accs.append((S.argmax(1)==y).mean())
            out[(g,lam)]=round(float(np.mean(accs)),4)
    return max(out.values())
for L in range(13):
